const docs = $input.all(0)[0]?.json?.results || [];
const tagsData = $input.all(1)[0]?.json?.results || [];
const correspData = $input.all(2)[0]?.json?.results || [];
const typesData = $input.all(3)[0]?.json?.results || [];
const notionPages = $input.all(4)[0]?.json?.results || [];

const tagMap = {}; tagsData.forEach(t => tagMap[t.id] = t.name);
const corrMap = {}; correspData.forEach(c => corrMap[c.id] = c.name);
const typeMap = {}; typesData.forEach(t => typeMap[t.id] = t.name);

const notionMap = {};
for (const page of notionPages) {
  const pId = page.properties['Paperless ID']?.number;
  if (pId) notionMap[pId] = page.id;
}

const requests = [];
for (const doc of docs) {
  const properties = {
    'Title': { title: [{ text: { content: doc.title } }] },
    'Correspondent': { rich_text: [{ text: { content: corrMap[doc.correspondent] || '' } }] },
    'Date Created': { date: { start: doc.created } },
    'Date Added': { date: { start: doc.added } },
    'ASN': { number: doc.archive_serial_number || null },
    'Has OCR': { checkbox: !!doc.content },
    'Paperless ID': { number: doc.id },
    'File Path': { rich_text: [{ text: { content: doc.original_file_name || '' } }] }
  };

  if (doc.document_type && typeMap[doc.document_type]) {
    properties['Document Type'] = { select: { name: typeMap[doc.document_type] } };
  }

  if (doc.tags && doc.tags.length > 0) {
    properties['Tags'] = { multi_select: doc.tags.map(tid => ({name: tagMap[tid] || `Tag${tid}`})) };
  }

  const pageId = notionMap[doc.id];
  if (pageId) {
    requests.push({ json: { method: 'PATCH', url: `https://api.notion.com/v1/pages/${pageId}`, body: { properties }, type: 'update' } });
  } else {
    requests.push({ json: { method: 'POST', url: 'https://api.notion.com/v1/pages', body: { parent: { database_id: '3da63d55-66c5-818c-bc85-fcbf681bdb59' }, properties }, type: 'add' } });
  }
}
return requests;

let added = 0, updated = 0, unchanged = 0, errors = 0;
const items = $input.all();
for (const item of items) {
  if (item.json.type === 'add') added++;
  else if (item.json.type === 'update') updated++;
}
return [{ json: { added, updated, unchanged, errors } }];
